    while (q.length > 0) {
        const sz = q.length;
        let maxVal = -Infinity;
        for (let i = 0; i < sz; i++) {
            const node = q.shift();
            if (node.val > maxVal) maxVal = node.val;
            if (node.left) q.push(node.left);
            if (node.right) q.push(node.right);
        }
        res.push(maxVal);
    }
